// === Tab: mySketch ===
//for #WccChallenge on theme of 'Kandinsky'.
//Decided didn't want to copy a specific Kandinsky piece, but make generative art based on individual forms Kandinsky used in various paintings.
//Also imortant to me that it was strongly reminiscent of Kandinsky, but still an original style.
//looks a bit 80's, but I think that shows Kandinsky's influence on the style of that era.
//Pallette taken from Kandinsky's painting "Moscow. Red Square" from 1916

let moscowColors= ["#345580","#D8CBBB","#D57A72","#EFB934","#BB302E","#338197"]

function setup() {
	createCanvas(1112, 834);
	background("#D8CBBB");
	noStroke();
	blendMode(MULTIPLY)

	//just for you Raph
  pixelDensity(1)


	//without this, looks terrible on mobile
 if(width>=height){
	 noOfBleeds= floor(windowWidth/90)
 }else{
	noOfBleeds= floor(windowHeight/75) 
 }

	//forms defined in other tab
	for(let i=0; i<noOfBleeds; i++){
	bleed(random(width), random(height), random(50, 300), floor(random(0, 6)), floor(random(0, 6)), floor(random(0, 6)));
	}

	for(let i=0;i<3; i++){
		glyph(random(width*0.1, width*0.9), random(height*0.1, height*0.9), random(width/10, width/6))
	}

	hash(random(width*0.1, width*0.9), random(height*0.1, height*0.9), random(100, 300))


	waves(random(width*0.2, width*0.8), random(height*0.2, height*0.8), random(300, 600))

	rayangle();
	rayangle();
	rayangle();
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}


// === Tab: forms functions ===
function glyph(x, y, s){
strokeCap(SQUARE)
stroke('#251723')
strokeWeight(random(1, 3))
fill('#251723')
push()
drawingContext.shadowOffsetX = 0;
	drawingContext.shadowOffsetY = 0;
	drawingContext.shadowBlur = s/20;
	drawingContext.shadowColor =random(moscowColors)
translate(x, y)
startVLines= floor(random(1, 3))	
for(let i=0; i<startVLines; i++){
xoff= random(-s/8, s/8)
line(xoff, -s/2,xoff, s/2)
}	
startHLines= floor(random(1, 5))
length=random(s/6, s/4)
	for(let i=0; i<startHLines; i++){
	yoff=random(-s*0.4, s*0.4)
	offset=random(-length/8, length/8)
		line(-length/2+offset, yoff, length/2+offset, yoff)
	}

swooshes= floor(random(0, 2))
	if(swooshes==1){
		let size=random(s/6, s/3)
		noFill()
		arc(xoff= random(-s/8, s/8), yoff=random(-s*0.4, s*0.4), size, size, random(0, PI),random(PI, TWO_PI) )
	}
pop()
}

function rayangle(){
 blendMode(DIFFERENCE)
	fill(random(moscowColors))
	pointer= createVector(random(width/3, width-width/3), random(height/3, height-height/3))
	offPointA=random(TWO_PI)
	offPointB= offPointA-random(-PI/6, PI/6)
  let pointer2= p5.Vector.fromAngle(offPointA, width)
	let pointer3=p5.Vector.fromAngle(offPointB, width)

	triangle(pointer.x, pointer.y, pointer2.x, pointer2.y, pointer3.x, pointer3.y)
}


function hash(x, y, s){

noOfVert=floor(random(3, 6))
noOfHor=floor(random(3, 6))
vSpacer= s/noOfVert+2
hSpacer= s/noOfHor+2

push()
translate(x, y)


for(let x=-s/2+hSpacer; x<s/2-hSpacer; x+=hSpacer){
	for(let y=-s/2+vSpacer; y<s/2-vSpacer; y+=vSpacer){
	let edge= color("#D8CBBB")
	edge.setAlpha(0)	
coloring= drawingContext.createRadialGradient(x+hSpacer/2, y+vSpacer/2, hSpacer*2, x+hSpacer/2+ random(-5, 5), y+vSpacer/2+ random(-5, 5), 0)
coloring.addColorStop(0, edge)
	coloring.addColorStop(1, random(moscowColors))
		drawingContext.fillStyle= coloring
		noStroke()
		rect(x, y, hSpacer, vSpacer)
}
	stroke('#251723')
	strokeWeight(random(1, 3))
	blendMode(MULTIPLY)
for(let x=-s/2+hSpacer; x<s/2; x+=hSpacer){
	line(x, -s/2, x, s/2)
}
for(let y=-s/2+vSpacer; y<s/2; y+=vSpacer){
	line(-s/2, y, s/2, y)
}
}	
	pop()
}

function waves(x, y, length){
stroke('#251723')
	strokeWeight(length/100)
	push()
	drawingContext.shadowOffsetX = 0;
	drawingContext.shadowOffsetY = 0;
	drawingContext.shadowBlur = length/50;
	drawingContext.shadowColor =random(moscowColors)
	translate(x, y)
	ellipse(x, y, 10)
	for(let yer=-length/8; yer<=length/8; yer+=length/8){
		noFill()
		beginShape()
		for(let xer=-length/2; xer<length/2; xer+=0.05){
			let wave= map(sin(xer/20),-1, 1, -length/20, length/20)
			vertex(xer, yer+wave)
		}
		endShape()
	}
	pop()
}


function bleed(x, y, r, c1, c2, c3, s){
	push()
	translate(x, y)
	var edge= color("#D8CBBB")
	edge.setAlpha(0)
	coloring= drawingContext.createRadialGradient(0, 0, r, 0, 0, 1)
	coloring.addColorStop(0, edge)
		coloring.addColorStop(0.333, moscowColors[c2])
	coloring.addColorStop(1, moscowColors[c1])
		drawingContext.fillStyle= coloring
	beginShape()
   let differ=random(1000)
	for(let i=0; i<=TWO_PI; i+=0.03){

		let xoffset= cos(i*2) +differ
		let yoffset= sin(i*2)+ differ
		let rnoised= map(noise(xoffset, yoffset), 0, 1, r*0.85, r*1.2)

	vertex(cos(i)*rnoised, sin(i)*rnoised)	

	}
	endShape()
	pop()
}

